'use client'

import { createClient } from '@/utils/supabase/client'
import { useRouter } from 'next/navigation'
import { useState } from 'react'
import { 
  approveReport, 
  rejectReport, 
  pullReport,   // <--- Ensure this is imported
  updateReport, 
  deleteReport 
} from './actions'

// --- HELPER: Lock Timezone to EST ---
function formatDateTime(dateStr: string | null) {
  if (!dateStr) return 'N/A'
  return new Intl.DateTimeFormat('en-US', {
    dateStyle: 'medium',
    timeStyle: 'short',
    timeZone: 'America/New_York', // Forces EST/EDT display regardless of user location
  }).format(new Date(dateStr))
}

export default function ReportDetailsClient({ 
  report, 
  userRole, 
  userId, 
  offenseTypes = [] // Default to empty array to prevent map errors
}: { 
  report: any, 
  userRole: string, 
  userId: string,
  offenseTypes?: any[] 
}) {
  const supabase = createClient()
  const router = useRouter()
  
  const [isProcessing, setIsProcessing] = useState(false)
  const [isEditing, setIsEditing] = useState(false)
  
  // Edit Form State
  const [editForm, setEditForm] = useState({
    offense_type_id: report.offense_type_id,
    date_of_offense: report.date_of_offense ? new Date(report.date_of_offense).toISOString().slice(0, 16) : '',
    notes: report.notes || '',
    description: report.report_explanation || ''
  })

  // --- PERMISSIONS LOGIC ---
  const isSubmitter = report.submitted_by === userId
  const isPending = report.status === 'pending_approval'
  
  // 1. Can Pull: Submitter can pull if pending
  const canPull = isSubmitter && isPending

  // 2. Can Approve: Admin, Commandant, or if assigned to your group
  // (This relies on backend RLS for security, this is just for UI visibility)
  const canApprove = 
    ['Commandant', 'Deputy Commandant', 'Admin'].includes(userRole) ||
    (report.current_approver_group_id && userRole !== 'Cadet') // Simplified check, refine based on your exact group logic

  // 3. Can Edit: Submitter (if revision needed) OR Current Approver (while pending)
  const canEdit = 
    (isSubmitter && report.status === 'needs_revision') ||
    (canApprove && isPending) || 
    userRole === 'Admin'

  // --- HANDLERS ---

  // FIX FOR "handlePull is not defined"
  const handlePull = async () => {
    if (!confirm('Are you sure? This will remove the report from the approval chain and return it to "Needs Revision" status.')) return
    
    setIsProcessing(true)
    const res = await pullReport(report.id)
    setIsProcessing(false)

    if (res.success) {
      router.refresh()
    } else {
      alert(`Error pulling report: ${res.error}`)
    }
  }

  const handleApprove = async () => {
    setIsProcessing(true)
    const res = await approveReport(report.id)
    setIsProcessing(false)
    if (res.success) {
      router.refresh()
    } else {
      alert(`Error: ${res.error}`)
    }
  }

  const handleReject = async () => {
    const reason = prompt("Enter reason for sending back (Revision Needed):")
    if (!reason) return
    
    setIsProcessing(true)
    const res = await rejectReport(report.id, reason)
    setIsProcessing(false)
    
    if (res.success) {
      router.refresh()
    } else {
      alert(`Error: ${res.error}`)
    }
  }

  const handleSaveEdit = async () => {
    setIsProcessing(true)
    const res = await updateReport(report.id, {
        offense_type_id: editForm.offense_type_id,
        date_of_offense: new Date(editForm.date_of_offense).toISOString(),
        notes: editForm.notes,
        report_explanation: editForm.description
    })
    setIsProcessing(false)

    if (res.success) {
        setIsEditing(false)
        router.refresh()
    } else {
        alert(`Update failed: ${res.error}`)
    }
  }

  const handleDelete = async () => {
    if(!confirm("Are you sure you want to permanently delete this report?")) return
    const res = await deleteReport(report.id)
    if (res.success) {
        router.push('/reports/submitted')
    } else {
        alert(res.error)
    }
  }

  return (
    <div className="w-full max-w-4xl mx-auto space-y-6 p-4">
      {/* Header / Actions */}
      <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4">
        <div>
           <h1 className="text-2xl font-bold">Report Details</h1>
           <p className="text-muted-foreground text-sm">ID: {report.id.slice(0,8)}</p>
        </div>
        
        <div className="flex gap-2 flex-wrap">
          {/* ACTION BUTTONS */}
          
          {canApprove && !isEditing && (
            <>
                <button onClick={handleApprove} disabled={isProcessing} className="bg-green-600 text-white px-4 py-2 rounded hover:bg-green-700 disabled:opacity-50">
                    Approve
                </button>
                <button onClick={handleReject} disabled={isProcessing} className="bg-amber-500 text-white px-4 py-2 rounded hover:bg-amber-600 disabled:opacity-50">
                    Kick Back
                </button>
            </>
          )}

          {canPull && !isEditing && (
            <button 
                onClick={handlePull} 
                disabled={isProcessing}
                className="bg-gray-100 border border-gray-300 text-gray-700 px-4 py-2 rounded hover:bg-gray-200 disabled:opacity-50"
            >
                Pull Report
            </button>
          )}

          {canEdit && !isEditing && (
            <button onClick={() => setIsEditing(true)} disabled={isProcessing} className="bg-blue-600 text-white px-4 py-2 rounded hover:bg-blue-700 disabled:opacity-50">
                Edit Report
            </button>
          )}
           
           {/* Admin Delete Override */}
           {userRole === 'Admin' && (
             <button onClick={handleDelete} className="text-red-500 hover:text-red-700 underline text-sm ml-2">Delete</button>
           )}
        </div>
      </div>

      {/* --- REPORT CONTENT --- */}
      <div className="bg-card border rounded-lg p-6 shadow-sm space-y-6">
        
        {isEditing ? (
            /* --- EDIT MODE --- */
            <div className="space-y-4 animate-in fade-in">
                <h3 className="font-semibold text-lg border-b pb-2">Editing Report</h3>
                
                {/* Offense Type Select */}
                <div>
                    <label className="block text-sm font-medium mb-1">Offense</label>
                    <select 
                        value={editForm.offense_type_id}
                        onChange={(e) => setEditForm({...editForm, offense_type_id: e.target.value})}
                        className="w-full p-2 border rounded bg-background"
                    >
                        {offenseTypes.map((ot: any) => (
                            <option key={ot.id} value={ot.id}>
                                {ot.offense_name} ({ot.demerits} demerits)
                            </option>
                        ))}
                    </select>
                </div>

                {/* Date Picker */}
                <div>
                    <label className="block text-sm font-medium mb-1">Date of Offense</label>
                    <input 
                        type="datetime-local" 
                        value={editForm.date_of_offense}
                        onChange={(e) => setEditForm({...editForm, date_of_offense: e.target.value})}
                        className="w-full p-2 border rounded bg-background"
                    />
                </div>

                {/* Description */}
                <div>
                    <label className="block text-sm font-medium mb-1">Description / Explanation</label>
                    <textarea 
                        value={editForm.description}
                        onChange={(e) => setEditForm({...editForm, description: e.target.value})}
                        className="w-full p-2 border rounded bg-background h-32"
                    />
                </div>

                <div className="flex justify-end gap-2 pt-4">
                    <button onClick={() => setIsEditing(false)} className="px-4 py-2 text-muted-foreground hover:text-foreground">Cancel</button>
                    <button onClick={handleSaveEdit} disabled={isProcessing} className="bg-blue-600 text-white px-4 py-2 rounded hover:bg-blue-700">Save Changes</button>
                </div>
            </div>
        ) : (
            /* --- VIEW MODE --- */
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                
                {/* Left Column */}
                <div className="space-y-4">
                    <div>
                        <h3 className="text-sm font-medium text-muted-foreground">Cadet</h3>
                        <p className="text-lg font-medium">{report.subject_cadet?.last_name}, {report.subject_cadet?.first_name}</p>
                        <p className="text-sm text-muted-foreground">{report.subject_cadet?.company?.company_name}</p>
                    </div>

                    <div>
                        <h3 className="text-sm font-medium text-muted-foreground">Offense</h3>
                        <div className="flex items-center gap-2">
                             <span className="font-medium">{report.offense_type?.offense_name}</span>
                             <span className="text-xs bg-gray-100 px-2 py-1 rounded border">Cat {report.offense_type?.policy_category}</span>
                        </div>
                        <p className="text-sm mt-1">{report.demerits_effective} Demerits</p>
                    </div>

                    <div>
                        <h3 className="text-sm font-medium text-muted-foreground">Date of Offense</h3>
                        <p>{formatDateTime(report.date_of_offense)}</p>
                    </div>
                </div>

                {/* Right Column */}
                <div className="space-y-4">
                    <div>
                        <h3 className="text-sm font-medium text-muted-foreground">Status</h3>
                        <div className="inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium bg-blue-100 text-blue-800 capitalize">
                            {report.status.replace('_', ' ')}
                        </div>
                    </div>

                    <div>
                        <h3 className="text-sm font-medium text-muted-foreground">Description</h3>
                        <div className="bg-muted/30 p-3 rounded-md text-sm whitespace-pre-wrap">
                            {report.report_explanation || "No description provided."}
                        </div>
                    </div>

                    {report.notes && (
                        <div>
                             <h3 className="text-sm font-medium text-muted-foreground">Notes</h3>
                             <p className="text-sm italic text-muted-foreground">{report.notes}</p>
                        </div>
                    )}
                </div>
            </div>
        )}
      </div>
    </div>
  )
}